-- Stable display sequence; existing internal IDs and relationships are unchanged.
CREATE SEQUENCE "case_contractDisplayId_seq";
ALTER TABLE "case" ADD COLUMN "contractDisplayId" INTEGER;
WITH numbered AS (SELECT id, row_number() OVER (ORDER BY "createdAt", id)::integer AS n FROM "case") UPDATE "case" c SET "contractDisplayId"=n.n FROM numbered n WHERE c.id=n.id;
SELECT setval('"case_contractDisplayId_seq"', COALESCE((SELECT MAX("contractDisplayId") FROM "case"),0)+1, false);
ALTER TABLE "case" ALTER COLUMN "contractDisplayId" SET DEFAULT nextval('"case_contractDisplayId_seq"');
ALTER SEQUENCE "case_contractDisplayId_seq" OWNED BY "case"."contractDisplayId";
ALTER TABLE "case" ALTER COLUMN "contractDisplayId" SET NOT NULL;
CREATE UNIQUE INDEX "case_contractDisplayId_key" ON "case"("contractDisplayId");
